import json

# Shift all rectangles towards top-left (subtract min row and min col across all rects)
rects = {
    9: {'h': 5, 'w': 3, 'r': 1, 'c': 1},
    7: {'h': 5, 'w': 5, 'r': 2, 'c': 7},
    2: {'h': 6, 'w': 3, 'r': 7, 'c': 10},
    4: {'h': 3, 'w': 3, 'r': 9, 'c': 2}
}

min_r = min(rects[k]['r'] for k in rects)  # 1
min_c = min(rects[k]['c'] for k in rects)  # 1

# Shift all so their min_r and min_c become 0
output = [[0]*14 for _ in range(14)]
for color, rect in rects.items():
    new_r = rect['r'] - min_r
    new_c = rect['c'] - min_c
    for r in range(new_r, new_r + rect['h']):
        for c in range(new_c, new_c + rect['w']):
            output[r][c] = color

action = {"action": "submit", "grid": output}
print(json.dumps(action, indent=2))

